// Real-browser checks for the media and file lanes (opt-in like the other *-browser tests):
//   MW_BROWSER=1 node --test test/unit/media-browser.test.mjs
// Chromium only, launched with chromiumArgs() (no non-local address is ever reached) against a
// throw-away server on 127.0.0.1 that serves the unbundled src/ modules and fixtures generated by
// test/fixtures/media/make-fixtures.mjs into a temporary directory. Checks:
//   U-FI-5 (browser half): a JPEG with a hand-built EXIF GPS segment has no EXIF after stripImage (canvas
//          re-encoding), and neither the camera make nor the GPS IFD survives
//   the IndexedDB chunk store (src/files/store-idb.js) with real IndexedDB: put, get, missing, reopen, destroy
//   preview.render() of a PNG through createImageBitmap with a resize, and the 24-megapixel header refusal
//   videoPoster() on the WebM fixture: an off-screen <video>, a JPEG poster, the container's size
import { test } from 'node:test';
import assert from 'node:assert/strict';
import http from 'node:http';
import fs from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import { fileURLToPath } from 'node:url';
import { chromiumArgs } from '../e2e/browser-args.mjs';
import { makeFixtures, hasFfmpeg } from '../fixtures/media/make-fixtures.mjs';

const ENABLED = process.env.MW_BROWSER === '1';
const ROOT = fileURLToPath(new URL('../../', import.meta.url));
const TYPES = { '.js': 'text/javascript', '.mjs': 'text/javascript', '.html': 'text/html', '.jpg': 'image/jpeg', '.webm': 'video/webm', '.mp4': 'video/mp4' };

const PAGE = `<!doctype html><meta charset="utf-8"><title>media lab</title><script type="module">
import { stripImage, jpegHasExif, jpegSegments } from '/src/media/strip.js';
import { IdbChunkStore, idbBackend } from '/src/files/store-idb.js';
import { previewPlan, render } from '/src/files/preview.js';
import { videoPoster } from '/src/media/poster.js';
const out = { errors: [] };
const has = (u8, s) => { const t = new TextEncoder().encode(s); outer: for (let i = 0; i + t.length <= u8.length; i++) { for (let k = 0; k < t.length; k++) if (u8[i + k] !== t[k]) continue outer; return true; } return false; };
async function run() {
  const src = new Uint8Array(await (await fetch('/fx/gps.jpg')).arrayBuffer());
  out.before = { exif: jpegHasExif(src), make: has(src, 'MagnetCam'), icc: has(src, 'MagnetCamProfile'), segments: jpegSegments(src).map((s) => s.name + ':' + s.ident) };
  const r = await stripImage(new Blob([src], { type: 'image/jpeg' }));
  const u8 = new Uint8Array(await r.blob.arrayBuffer());
  out.after = { exif: jpegHasExif(u8), make: has(u8, 'MagnetCam'), icc: has(u8, 'MagnetCamProfile'), gps: has(u8, 'GPS'), mime: r.mime, w: r.w, h: r.h, removed: r.removed, segments: jpegSegments(u8).map((s) => s.name + ':' + s.ident), magic: u8[0] === 0xff && u8[1] === 0xd8 };
  const small = await stripImage(new Blob([src], { type: 'image/jpeg' }), { maxSide: 100, type: 'image/jpeg' });
  out.small = { w: small.w, h: small.h };
  // IndexedDB chunk store
  const backend = idbBackend();
  const s = new IdbChunkStore(4, { name: 'lab', length: 10, backend });
  const put = (i, b) => new Promise((res) => s.put(i, b, res));
  out.idb = { put0: await put(0, new Uint8Array([1, 2, 3, 4])), put2: await put(2, new Uint8Array([7, 8])) };
  out.idb.missing = await s.missing();
  const again = new IdbChunkStore(4, { name: 'lab', length: 10, backend });
  out.idb.reopened = Array.from(await again.getAsync(2));
  await new Promise((res) => s.destroy(res));
  out.idb.afterDestroy = (await again.getAsync(0)) === undefined;
  // preview
  const c = document.createElement('canvas');
  c.width = 3000; c.height = 2000;
  c.getContext('2d').fillRect(0, 0, 10, 10);
  const png = await new Promise((res) => c.toBlob(res, 'image/png'));
  const head = new Uint8Array(await png.slice(0, 65536).arrayBuffer());
  const plan = previewPlan(head);
  const shown = await render(png, plan, { maxSide: 300 });
  out.preview = { plan: plan.kind, w: shown.w, h: shown.h, url: shown.url.slice(0, 5) };
  const bomb = head.slice();
  new DataView(bomb.buffer).setUint32(16, 65535); new DataView(bomb.buffer).setUint32(20, 65535);
  out.preview.bomb = previewPlan(bomb).reason;
  // poster from the WebM fixture
  const webm = await (await fetch('/fx/tags.webm')).blob();
  const p = await videoPoster(new Blob([webm], { type: 'video/webm' }));
  const pb = new Uint8Array(await p.blob.arrayBuffer());
  out.poster = { mime: p.mime, w: p.w, h: p.h, jpeg: pb[0] === 0xff && pb[1] === 0xd8, duration: Math.round(p.duration * 10) / 10 };
}
run().then(() => { window.__out = out; }, (e) => { out.errors.push(String(e && e.stack || e)); window.__out = out; });
</script>`;

test('media lane in Chromium: EXIF GPS removed by canvas, IndexedDB chunk store, preview render, video poster', {
  skip: !ENABLED ? 'set MW_BROWSER=1 (opens Chromium on 127.0.0.1)' : !hasFfmpeg() ? 'ffmpeg not on PATH (fixtures)' : false,
  timeout: 180000,
}, async () => {
  const { chromium } = await import('playwright');
  const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'mw-media-browser-'));
  const fx = await makeFixtures(dir, { only: ['gpsJpeg', 'webmTags'] });
  const server = http.createServer(async (req, res) => {
    const p = decodeURIComponent(new URL(req.url, 'http://127.0.0.1').pathname);
    let file = null;
    if (p === '/') {
      res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
      return res.end(PAGE);
    }
    if (p.startsWith('/src/')) file = path.join(ROOT, p);
    else if (p === '/fx/gps.jpg') file = fx.gpsJpeg;
    else if (p === '/fx/tags.webm') file = fx.webmTags;
    if (!file || !file.startsWith(ROOT) && !file.startsWith(dir)) {
      res.writeHead(404);
      return res.end();
    }
    try {
      const data = await fs.readFile(file);
      res.writeHead(200, { 'Content-Type': TYPES[path.extname(file)] || 'application/octet-stream' });
      res.end(data);
    } catch (_) {
      res.writeHead(404);
      res.end();
    }
  });
  await new Promise((r) => server.listen(0, '127.0.0.1', r));
  const base = 'http://127.0.0.1:' + server.address().port + '/';
  const browser = await chromium.launch({ args: chromiumArgs({ allowRemote: false }) });
  try {
    const page = await browser.newPage();
    await page.goto(base);
    await page.waitForFunction(() => window.__out, null, { timeout: 60000 });
    const out = await page.evaluate(() => window.__out);
    assert.deepEqual(out.errors, []);
    assert.equal(out.before.exif, true, 'the fixture carries EXIF');
    assert.equal(out.before.make, true);
    assert.equal(out.after.exif, false, 'no EXIF after re-encoding');
    assert.equal(out.after.make, false, 'the camera make is gone');
    assert.equal(out.after.magic, true);
    assert.equal(out.after.mime, 'image/jpeg');
    assert.deepEqual([out.after.w, out.after.h], [320, 240]);
    assert.ok(!out.after.segments.some((s) => s.startsWith('APP1')), 'no APP1 segment: ' + out.after.segments.join(','));
    // Chromium writes its own sRGB ICC_PROFILE into every canvas JPEG; the uploaded profile is gone
    assert.equal(out.before.icc, true);
    assert.equal(out.after.icc, false, 'the original ICC profile is gone');
    assert.deepEqual(out.after.removed, ['exif', 'icc', 'thumbnail']);
    assert.deepEqual(out.small, { w: 100, h: 75 });
    assert.deepEqual(out.idb, { put0: null, put2: null, missing: [1], reopened: [7, 8], afterDestroy: true });
    assert.deepEqual(out.preview, { plan: 'image', w: 300, h: 200, url: 'blob:', bomb: 'too-large' });
    assert.equal(out.poster.mime, 'image/jpeg');
    assert.equal(out.poster.jpeg, true);
    assert.deepEqual([out.poster.w, out.poster.h], [160, 120]);
  } finally {
    await browser.close();
    await new Promise((r) => server.close(r));
    await fs.rm(dir, { recursive: true, force: true });
  }
});
